def get_isbn_10_and_13(isbns: str | list[str]) -> tuple[list[str], list[str]]:
    """Separate IA ISBNs by length, discarding values without an ISBN format."""
    isbn_10, isbn_13 = [], []
    for value in [isbns] if isinstance(isbns, str) else isbns or []:
        if not isinstance(value, str):
            continue
        isbn = re.sub(r'[\s-]+', '', value).upper()
        if re.fullmatch(r'\d{9}[\dX]', isbn):
            isbn_10.append(isbn)
        elif re.fullmatch(r'\d{13}', isbn):
            isbn_13.append(isbn)
    return isbn_10, isbn_13


def get_publisher_and_place(
    publishers: str | list[str],
) -> tuple[list[str], list[str]]:
    """Split IA's optional ``Place: Publisher`` entries into edition fields."""
    names, places = [], []
    for value in [publishers] if isinstance(publishers, str) else publishers or []:
        if not isinstance(value, str):
            continue
        place, separator, name = value.partition(':')
        name = name.strip() if separator else place.strip()
        if name:
            names.append(name)
            if separator and place.strip():
                places.append(place.strip())
    return names, places


class MultiDict(MutableMapping):
    """Ordered Dictionary that can store multiple values.

    >>> d = MultiDict()
    >>> d['x'] = 1
    >>> d['x'] = 2
    >>> d['y'] = 3
    >>> d['x']
    2
    >>> d['y']
    3
    >>> d['z']
    Traceback (most recent call last):
        ...
    KeyError: 'z'
    >>> list(d)
    ['x', 'x', 'y']
    >>> list(d.items())
    [('x', 1), ('x', 2), ('y', 3)]
    >>> list(d.multi_items())
    [('x', [1, 2]), ('y', [3])]
    """

    def __init__(self, items=(), **kw):
        self._items = []

        for k, v in items:
            self[k] = v
        self.update(kw)

    def __getitem__(self, key):
        if values := self.getall(key):
            return values[-1]
        else:
            raise KeyError(key)

    def __setitem__(self, key, value):
        self._items.append((key, value))

    def __delitem__(self, key):
        self._items = [(k, v) for k, v in self._items if k != key]
